def clocks():
    first=time.monotonic_ns()
    boot_time=time.clock_gettime_ns(time.CLOCK_BOOTTIME)
    wall=time.time_ns();last=time.monotonic_ns()
    value=dict(boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip(),
               mono=first,boot_time=boot_time,wall=wall,span=last-first)
    return d.sample(value)

def record(name,value):
    c.record(name,value)

def outputs_absent(phase):
    for name in OUTPUTS[phase]:
        c.o.require(not os.path.lexists(ROOT/name),'phase output already exists: '+name)

def enter_phase(phase):
    c.o.require(not os.path.lexists(ROOT/'terminal.json'),'attempt terminal')
    index=PHASES.index(phase)
    for n,p in enumerate(PHASES):
        begun=os.path.lexists(ROOT/(p+'-start.json'))
        done=os.path.lexists(ROOT/(p+'-done.json'))
        c.o.require((begun and done) if n<index else (not begun and not done),
                    'phase already consumed, incomplete, or out of order')
        if n>=index:outputs_absent(p)
    record(phase+'-start.json',dict(phase=phase,clock=clocks()))

def run_phase(phase,action):
    # A durable intent without completion is itself a stop after process loss.
    try:
        enter_phase(phase)
        result=action()
        record(phase+'-done.json',dict(phase=phase,clock=clocks(),result=result))
        return result
    except BaseException as exc:
        if not os.path.lexists(ROOT/'terminal.json'):
            record('terminal.json',dict(phase=phase,error_type=type(exc).__name__,reason=str(exc),
                                       submission_started=os.path.lexists(ROOT/'submit-start.json')))
        raise

