def timestamp(value):
    parsed=datetime.strptime(value,'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    c.o.require(parsed.strftime('%Y-%m-%dT%H:%M:%SZ')==value,'noncanonical envelope time')
    return int(parsed.timestamp())*d.SECOND

